toolScript:
// Constants
        const CREDIT_CARD_WIDTH_MM = 85.60;
        let pxPerMm = 1;
        // Elements
        const slider = document.getElementById('calibration-slider');
        const calBox = document.getElementById('calibration-box');
        const canvas = document.getElementById('wrist-canvas');
        const ctx = canvas.getContext('2d');
        function init() {
            // Set initial canvas size
            resizeCanvas();
            window.addEventListener('resize', resizeCanvas);
            // Slider Event
            slider.addEventListener('input', () => {
                updateCalibration();
                drawVisualization();
            });
            // Initial Draw
            updateCalibration();
            drawVisualization();
        }
        function resizeCanvas() {
            const container = document.getElementById('canvas-container');
            canvas.width = container.clientWidth;
            canvas.height = container.clientHeight;
            drawVisualization();
        }
        function updateCalibration() {
            const widthPx = parseInt(slider.value);
            calBox.style.width = widthPx + 'px';
            // If box (widthPx) equals 85.6mm, then:
            pxPerMm = widthPx / CREDIT_CARD_WIDTH_MM;
        }
        function setWatch(size) {
            document.getElementById('in-watch-size').value = size;
            drawVisualization();
        }
        function drawVisualization() {
            // Clear
            ctx.clearRect(0, 0, canvas.width, canvas.height);
            // Inputs
            const wristSizeInput = parseFloat(document.getElementById('in-wrist').value);
            const unit = document.getElementById('in-unit').value;
            const watchDiameterMm = parseFloat(document.getElementById('in-watch-size').value);
            if (!wristSizeInput || !watchDiameterMm) return;
            // Convert wrist to mm
            let wristCircumferenceMm = (unit === 'inch') ? wristSizeInput * 25.4 : wristSizeInput * 10;
            // Calculate Wrist "Width" (Top down view)
            // Assuming wrist is a flattened ellipse. 
            // A simplified model: Width is roughly Circumference / 3.3 (slightly flatter than circle PI)
            const wristWidthMm = wristCircumferenceMm / 3.3;
            // Dimensions in Pixels
            const wWidthPx = wristWidthMm * pxPerMm;
            const watchDiaPx = watchDiameterMm * pxPerMm;
            const centerX = canvas.width / 2;
            const centerY = canvas.height / 2;
            // 1. Draw Wrist
            ctx.fillStyle = '#1e293b'; // Slate 800
            ctx.beginPath();
            // Draw a rounded rectangle/ellipse for the wrist
            // Height of wrist is arbitrary for visual, say 60% of width
            const wHeightPx = wWidthPx * 0.6;
            ctx.ellipse(centerX, centerY, wWidthPx / 2, wHeightPx / 2, 0, 0, 2 * Math.PI);
            ctx.fill();
            // Wrist shading
            ctx.strokeStyle = '#334155';
            ctx.lineWidth = 2;
            ctx.stroke();
            // 2. Draw Watch Case
            ctx.fillStyle = '#e2e8f0'; // Light slate
            ctx.beginPath();
            ctx.arc(centerX, centerY, watchDiaPx / 2, 0, 2 * Math.PI);
            ctx.fill();
            // Watch Bezel/Rim
            ctx.strokeStyle = '#94a3b8';
            ctx.lineWidth = 3;
            ctx.stroke();
            // 3. Draw Lugs (Estimation)
            // Lugs usually extend 1.25x diameter total (lug to lug)
            const lugToLugMm = watchDiameterMm * 1.25;
            const lugToLugPx = lugToLugMm * pxPerMm;
            ctx.strokeStyle = '#e2e8f0';
            ctx.lineWidth = 4;
            ctx.beginPath();
            // Top Lugs
            ctx.moveTo(centerX - (watchDiaPx / 3), centerY - (watchDiaPx / 2));
            ctx.lineTo(centerX - (watchDiaPx / 3), centerY - (lugToLugPx / 2));
            ctx.moveTo(centerX + (watchDiaPx / 3), centerY - (watchDiaPx / 2));
            ctx.lineTo(centerX + (watchDiaPx / 3), centerY - (lugToLugPx / 2));
            // Bottom Lugs
            ctx.moveTo(centerX - (watchDiaPx / 3), centerY + (watchDiaPx / 2));
            ctx.lineTo(centerX - (watchDiaPx / 3), centerY + (lugToLugPx / 2));
            ctx.moveTo(centerX + (watchDiaPx / 3), centerY + (watchDiaPx / 2));
            ctx.lineTo(centerX + (watchDiaPx / 3), centerY + (lugToLugPx / 2));
            ctx.stroke();
            // 4. Draw Strap
            const strapWidthPx = watchDiaPx * 0.5; // typically 20mm strap on 40mm watch
            ctx.fillStyle = '#475569';
            // Top Strap
            ctx.fillRect(centerX - strapWidthPx / 2, 0, strapWidthPx, centerY - (lugToLugPx / 2));
            // Bottom Strap
            ctx.fillRect(centerX - strapWidthPx / 2, centerY + (lugToLugPx / 2), strapWidthPx, canvas.height);
            // 5. Warning Text if Overhang
            if (lugToLugMm > wristWidthMm) {
                ctx.fillStyle = '#EE6C4D';
                ctx.font = 'bold 12px Inter';
                ctx.textAlign = 'center';
                ctx.fillText('WARNING: Lugs may overhang', centerX, centerY + (lugToLugPx / 2) + 20);
            }
        }
        // Initialize
        document.addEventListener('DOMContentLoaded', init);
        // --- SCROLL LOGIC ---
